const j = { ...$json };

j.summary = j.text ?? j.summary;

delete j.text;

j.update_module = j.contact_id ? 'Contacts' : (j.lead_id ? 'Leads' : null);
j.update_id = j.contact_id || j.lead_id || null;

return [{
  json: j
}];

const j = $json;
const record = {
  previous_summary: j.summary
};
if (j.update_module === 'Leads') {
  record.Lead_Status = 'Дзвінок здійснено';
}
return [{ json: { ...j, update_payload: { data: [record] } } }];

// ============================================================
// Example Company — Postcall webhook parser (Happ.tools / ElevenLabs-style payload)
// Джерело даних: transcript[].tool_calls, де "Postcall" — звичайний
// tool, який агент повинен явно викликати (див. Секцію 13 промпту v3.0).
// tool_name у логах приходить як числовий індекс (ненадійний для
// матчингу за назвою), тому Postcall-виклик визначається за
// СИГНАТУРОЮ параметрів (наявність ключів AI_Score/AI_Context/
// phone_number), а не за назвою tool'а.
// ============================================================

const b = $json.body || $json;
const data = b.data || b;
const dv = data.conversation_initiation_client_data?.dynamic_variables || {};
const analysis = data.analysis || {};
const transcript = data.transcript || [];

// ---------- Утиліта: подвійний JSON.parse ----------
// params_as_json / result_value приходять як рядок, що сам є
// JSON-рядком з екранованим JSON усередині (double-encoded).
function safeDoubleParse(raw) {
  if (raw === undefined || raw === null) return null;
  let step1;
  try {
    step1 = JSON.parse(raw);
  } catch {
    return null;
  }
  if (typeof step1 === "object" && step1 !== null) return step1;
  if (typeof step1 === "string") {
    try {
      const step2 = JSON.parse(step1);
      return typeof step2 === "object" && step2 !== null ? step2 : null;
    } catch {
      return null;
    }
  }
  return null;
}

// Очікувані ключі Postcall tool — використовуються як "відбиток"
// для розпізнавання потрібного tool_call серед усіх викликів за дзвінок.
const POSTCALL_SIGNATURE_KEYS = [
  "phone_number", "lead_id", "contact_id", "call_success",
  "human_handoff", "handoff_reason", "summary", "AI_Context", "AI_Score"
];

function looksLikePostcallParams(obj) {
  if (!obj || typeof obj !== "object") return false;
  const matchCount = POSTCALL_SIGNATURE_KEYS.filter(k => k in obj).length;
  // Вважаємо це Postcall-викликом, якщо збігається щонайменше 4
  // з 9 очікуваних ключів (з запасом на випадок часткового заповнення).
  return matchCount >= 4;
}

// ---------- Пошук Postcall tool call у всьому транскрипті ----------
let postcallParams = null;
let postcallToolInvoked = false;
let postcallCallSucceeded = null; // is_error з tool_results, якщо знайдено

for (let i = 0; i < transcript.length; i++) {
  const calls = transcript[i].tool_calls || [];
  const results = transcript[i].tool_results || [];
  for (let j = 0; j < calls.length; j++) {
    const parsed = safeDoubleParse(calls[j].params_as_json);
    if (looksLikePostcallParams(parsed)) {
      postcallParams = parsed;
      postcallToolInvoked = true;
      // tool_results зазвичай на тому ж індексі в межах цього ж turn
      const matchingResult = results[j] || results[0];
      if (matchingResult) postcallCallSucceeded = !matchingResult.is_error;
      break;
    }
  }
  if (postcallParams) break;
}

// ---------- end_call reason (для fallback і діагностики) ----------
let endCallReason = null;
for (let i = transcript.length - 1; i >= 0; i--) {
  const calls = transcript[i].tool_calls || [];
  for (const tc of calls) {
    const parsed = safeDoubleParse(tc.params_as_json);
    if (parsed && "reason" in parsed && !looksLikePostcallParams(parsed)) {
      endCallReason = parsed.reason || null;
    }
  }
  if (endCallReason) break;
}

// ---------- Фінальні поля ----------
// Пріоритет: значення, які агент реально передав у Postcall tool.
// Fallback (лише якщо tool узагалі не викликано — сигнал, що
// промпт ще не оновлено чи агент проігнорував інструкцію) —
// евристики зі старої версії, плюс явний прапорець для моніторингу.

const phoneNumber = postcallParams?.phone_number ?? dv.phone_number ?? null;
const leadId = postcallParams?.lead_id ?? dv.lead_id ?? null;
const contactId = postcallParams?.contact_id ?? dv.contact_id ?? null;

const callSuccess =
  postcallParams?.call_success ??
  (Array.isArray(transcript) && transcript.length > 2);

const reasonTextForFallback = (endCallReason || "").toLowerCase();
const handoffFallback =
  /(handoff|manager|callback|contact|human|менеджер|передзвон|перетелефон)/i.test(reasonTextForFallback);

const humanHandoff =
  typeof postcallParams?.human_handoff === "boolean"
    ? postcallParams.human_handoff
    : handoffFallback;

const handoffReason =
  postcallParams?.handoff_reason ??
  (humanHandoff ? endCallReason : null);

let summary =
  postcallParams?.summary ??
  analysis.transcript_summary ??
  null;

if (
  summary &&
  (
    summary.includes("Please provide the customer service conversation") ||
    summary.includes("The conversation transcript was not included in your prompt") ||
    summary.includes("You did not provide the customer service conversation text")
  )
) {
  summary = null;
}

const aiScoreRaw = postcallParams?.AI_Score ?? null;
const aiScore = typeof aiScoreRaw === "number" ? aiScoreRaw : (Number.isFinite(Number(aiScoreRaw)) ? Number(aiScoreRaw) : null);

// ---------- OUTPUT ----------
return [{
  json: {
    call_id: data.conversation_id || null,
    agent_name: data.agent_name || "Outbound",
    call_type: dv.call_type || null,
    phone_number: phoneNumber,
    lead_id: leadId,
    contact_id: contactId,
    duration_seconds: data.metadata?.call_duration_secs || 0,
    call_success: callSuccess,
    human_handoff: humanHandoff,
    handoff_reason: handoffReason,
    summary: summary,
    AI_Score: aiScore,
    AI_Context: postcallParams?.AI_Context ?? null,

    // --- Діагностика для моніторингу впровадження промпту v3.0 ---
    // Якщо postcall_tool_invoked = false на новій версії промпту —
    // це сигнал, що агент все ще НЕ викликає Postcall tool явно,
    // і Секцію 13 промпту треба переглянути/посилити ще раз.
    postcall_tool_invoked: postcallToolInvoked,
    postcall_tool_error: postcallToolInvoked ? (postcallCallSucceeded === false) : null
  }
}];

