      ...$json,

      summary: output.summary,
      handoff_reason: output.handoff_reason,

      AI_Score: output.ai_score,

      BANT_Budget: output.bant.budget,
      BANT_Authority: output.bant.authority,
      BANT_Need: output.bant.need,
      BANT_Timeline: output.bant.timeline
    }
  }
];

